/**
 * Format full name to hide last name for privacy
 * Example: "Karla Almeida" -> "Karla A."
 * Example: "João da Silva Santos" -> "João S."
 */
export const formatPrivateName = (fullName) => {
  if (!fullName || typeof fullName !== 'string') {
    return 'User';
  }

  const nameParts = fullName.trim().split(' ').filter(part => part.length > 0);

  if (nameParts.length === 0) {
    return 'User';
  }

  if (nameParts.length === 1) {
    // Only first name provided
    return nameParts[0];
  }

  // Get first name and last name initial
  const firstName = nameParts[0];
  const lastNameInitial = nameParts[nameParts.length - 1][0].toUpperCase();

  return `${firstName} ${lastNameInitial}.`;
};
