import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../../supabaseClient';
import { useAuth } from '../../context/AuthContext';
import { formatPrivateName } from '../../utils/nameFormatter';
import { MessageCircle, User, Briefcase, Search } from 'lucide-react';
import './BrowseArtists.css';

function BrowseArtists() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [artists, setArtists] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedArtist, setSelectedArtist] = useState(null);
  const [showProjectModal, setShowProjectModal] = useState(false);
  const [myProjects, setMyProjects] = useState([]);

  useEffect(() => {
    if (user?.id) {
      loadArtists();
      loadMyProjects();
    }
  }, [user]);

  const loadArtists = async () => {
    try {
      setLoading(true);

      // Get all approved artists
      const { data: artistsDate, error: artistsError } = await supabase
        .from('profiles')
        .select('*')
        .eq('user_type', 'artista')
        .eq('approval_status', 'approved')
        .order('created_at', { ascending: false });

      if (artistsError) throw artistsError;

      // For each artist, get their portfolio images
      const artistsWithPortfolios = await Promise.all(
        (artistsDate || []).map(async (artist) => {
          const { data: portfolioDate } = await supabase
            .from('artist_portfolios')
            .select('image_url')
            .eq('artist_id', artist.id)
            .order('created_at', { ascending: false })
            .limit(9);

          return {
            ...artist,
            portfolio_images: portfolioDate?.map(p => p.image_url) || []
          };
        })
      );

      setArtists(artistsWithPortfolios);
    } catch (error) {
      console.error('Error loading artists:', error);
    } finally {
      setLoading(false);
    }
  };

  const loadMyProjects = async () => {
    try {
      const { data, error } = await supabase
        .from('projects')
        .select('id, title, status')
        .eq('architect_id', user.id)
        .eq('status', 'open')
        .order('created_at', { ascending: false });

      if (error) throw error;
      setMyProjects(data || []);
    } catch (error) {
      console.error('Error loading projects:', error);
    }
  };

  const handleSendMessage = async (artistId) => {
    try {
      // Create or get existing conversation
      const { data: existingConv } = await supabase
        .from('conversations')
        .select('id')
        .or(`and(participant1_id.eq.${user.id},participant2_id.eq.${artistId}),and(participant1_id.eq.${artistId},participant2_id.eq.${user.id})`)
        .single();

      if (existingConv) {
        navigate('/dashboard/messages', {
          state: { conversationId: existingConv.id, artistId }
        });
        return;
      }

      // Create new conversation
      const { data: newConv, error } = await supabase
        .from('conversations')
        .insert({
          participant1_id: user.id,
          participant2_id: artistId,
          last_message_at: new Date().toISOString()
        })
        .select()
        .single();

      if (error) throw error;

      navigate('/dashboard/messages', {
        state: { conversationId: newConv.id, artistId }
      });
    } catch (error) {
      console.error('Error creating conversation:', error);
      alert('Error starting conversation. Please try again.');
    }
  };

  const handleRequestApplication = (artist) => {
    setSelectedArtist(artist);
    setShowProjectModal(true);
  };

  const handleInviteToProject = async (projectId) => {
    try {
      // Create a message inviting the artist to apply
      const { data: conv } = await supabase
        .from('conversations')
        .select('id')
        .or(`and(participant1_id.eq.${user.id},participant2_id.eq.${selectedArtist.id}),and(participant1_id.eq.${selectedArtist.id},participant2_id.eq.${user.id})`)
        .single();

      let conversationId = conv?.id;

      if (!conversationId) {
        const { data: newConv, error: newConvError } = await supabase
          .from('conversations')
          .insert({
            participant1_id: user.id,
            participant2_id: selectedArtist.id,
            last_message_at: new Date().toISOString()
          })
          .select()
          .single();

        if (newConvError) throw newConvError;
        conversationId = newConv.id;
      }

      const project = myProjects.find(p => p.id === projectId);

      // Send invitation message
      await supabase
        .from('messages')
        .insert({
          conversation_id: conversationId,
          sender_id: user.id,
          receiver_id: selectedArtist.id,
          content: `Hello! I would like to invite you to apply for my project: "${project.title}". Please check the details and submit your proposal!`,
          is_read: false
        });

      alert('Invitation sent successfully!');
      setShowProjectModal(false);
      setSelectedArtist(null);
    } catch (error) {
      console.error('Error sending invitation:', error);
      alert('Error sending invitation. Please try again.');
    }
  };

  const filteredArtists = artists.filter(artist => {
    const displayName = formatPrivateName(artist.full_name);
    return displayName.toLowerCase().includes(searchTerm.toLowerCase());
  });

  if (loading) {
    return <div className="loading">Loading artists...</div>;
  }

  return (
    <div className="browse-artists-container">
      <div className="browse-header">
        <div>
          <h2 className="section-title">🎨 Browse Artists</h2>
          <p className="subtitle">Discover talented 3D artists and their portfolios</p>
        </div>

        <div className="search-box">
          <Search size={20} />
          <input
            type="text"
            placeholder="Search artists..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="search-input"
          />
        </div>
      </div>

      {filteredArtists.length === 0 ? (
        <div className="empty-state">
          <User size={64} className="empty-icon" />
          <p className="empty-state-title">No artists found</p>
          <p className="empty-state-text">
            {searchTerm ? 'Try a different search term' : 'No artists available at the moment'}
          </p>
        </div>
      ) : (
        <div className="artists-grid">
          {filteredArtists.map((artist) => (
            <div key={artist.id} className="artist-card">
              {/* Artist Header */}
              <div className="artist-card-header">
                <div className="artist-avatar">
                  {artist.profile_photo ? (
                    <img src={artist.profile_photo} alt={formatPrivateName(artist.full_name)} />
                  ) : (
                    <div className="avatar-placeholder">
                      <User size={32} />
                    </div>
                  )}
                </div>
                <div className="artist-info">
                  <h3 className="artist-name">{formatPrivateName(artist.full_name)}</h3>
                  {artist.location && (
                    <p className="artist-location">📍 {artist.location}</p>
                  )}
                </div>
              </div>

              {/* Portfolio Grid */}
              <div className="portfolio-grid">
                {artist.portfolio_images.length === 0 ? (
                  <div className="no-portfolio">
                    <p>No portfolio images yet</p>
                  </div>
                ) : (
                  artist.portfolio_images.slice(0, 9).map((imageUrl, index) => (
                    <div key={index} className="portfolio-image">
                      <img src={imageUrl} alt={`Portfolio ${index + 1}`} />
                    </div>
                  ))
                )}
              </div>

              {/* Action Buttons */}
              <div className="artist-actions">
                <button
                  onClick={() => navigate(`/artist-profile/${artist.id}`)}
                  className="btn-view-profile"
                >
                  View Profile
                </button>
                <button
                  onClick={() => handleSendMessage(artist.id)}
                  className="btn-message"
                  title="Send Message"
                >
                  <MessageCircle size={18} />
                </button>
                <button
                  onClick={() => handleRequestApplication(artist)}
                  className="btn-invite"
                  title="Invite to Project"
                >
                  <Briefcase size={18} />
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Project Selection Modal */}
      {showProjectModal && selectedArtist && (
        <div className="modal-overlay" onClick={() => setShowProjectModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>Invite {formatPrivateName(selectedArtist.full_name)} to Project</h3>
              <button onClick={() => setShowProjectModal(false)} className="close-button">×</button>
            </div>

            <div className="modal-body">
              {myProjects.length === 0 ? (
                <div className="empty-projects">
                  <p>You don't have any open projects yet.</p>
                  <button
                    onClick={() => navigate('/dashboard/architect/post-project')}
                    className="btn-primary"
                  >
                    Create a Project
                  </button>
                </div>
              ) : (
                <div className="projects-list">
                  <p className="modal-instruction">Select a project to invite this artist:</p>
                  {myProjects.map((project) => (
                    <div key={project.id} className="project-option">
                      <div className="project-option-info">
                        <h4>{project.title}</h4>
                        <span className="project-status">{project.status}</span>
                      </div>
                      <button
                        onClick={() => handleInviteToProject(project.id)}
                        className="btn-select-project"
                      >
                        Send Invite
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default BrowseArtists;
